window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-66ff0e305612c605"]={"versions": [{"id": "FIG-66ff0e305612c605", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).\n</li><li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (Payload/Header).\n</li><li><code>Length</code>: Länge der übergebenen Daten in Byte.\n</li></ul>\n</li><li><strong>Knotenelemente</strong>:\n<ul class=\"fig-list\"><li>Initialknoten (Startpunkt der Prüfung).\n</li><li>Zwei Entscheidungsknoten (Rauten) zur sequenziellen Validierung von Zeigern und Datenlänge.\n</li><li>Drei Aktivitätsendknoten (<code>no input</code>, <code>input ok</code>, <code>wrong input</code>), korrespondierend zu den Fehler- bzw. Erfolgszuständen.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.\n</li><li>Erste Prüfung am oberen Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no input</code> (führt im übergeordneten Ablauf zu <code>E2E_E_INPUTERR_NULL</code>).\n</li><li>Pfad <code>[TRUE]</code>: Übergang zur nachfolgenden Längenprüfung.\n</li></ul>\n</li><li>Zweite Prüfung am unteren Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>Length == Config-&gt;DataLength/8</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong input</code> (führt im übergeordneten Ablauf zu <code>E2E_E_INPUTERR_WRONG</code>).\n</li><li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input ok</code> (erlaubt die Fortsetzung der Schutzfunktion mit Write Counter, CRC-Berechnung etc.).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\"><li>Zeiger dürfen nicht <code>NULL</code> sein, andernfalls ist die Ausführung sofort mit Null-Pointer-Fehler zu beenden.\n</li><li>Die übergebene Bytezahl <code>Length</code> muss exakt der in <code>Config-&gt;DataLength</code> spezifizierten Bitlänge dividiert durch 8 entsprechen.\n</li><li>Bei abweichender Länge darf keine Manipulation oder Berechnung auf dem Puffer erfolgen; es ist zwingend der Fehlerstatus für inkorrekte Eingaben zurückzugeben.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-13a23f18d89df96e", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).\n</li><li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array.\n</li><li><code>Length</code>: Länge der Daten in Byte.\n</li><li><code>Offset</code>: Offset-Position des Headers in Byte (implizit/aus Konfiguration referenziert).\n</li></ul>\n</li><li><strong>Knotenelemente</strong>:\n<ul class=\"fig-list\"><li>Initialknoten.\n</li><li>Zwei Entscheidungsknoten (Rauten) zur Zeiger- und Bereichsprüfung.\n</li><li>Drei Aktivitätsendknoten (<code>no</code>, <code>input</code>, <code>wrong</code>), repräsentierend <code>no input</code>, <code>input ok</code> und <code>wrong input</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.\n</li><li>Erste Prüfung am oberen Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no</code> (entspricht <code>no input</code>).\n</li><li>Pfad <code>[TRUE]</code>: Weiterleitung zur kombinierten Längenprüfung.\n</li></ul>\n</li><li>Zweite Prüfung am unteren Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong</code> (entspricht <code>wrong input</code>).\n</li><li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input</code> (entspricht <code>input ok</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\"><li>Zeiger dürfen nicht <code>NULL</code> sein.\n</li><li>Die übergebene Länge <code>Length</code> muss strikt gleich <code>Config-&gt;DataLength/8</code> sein und muss zusätzlich mindestens <code>Offset + 2</code> Byte umfassen, um sicherzustellen, dass die CRC- und Counter-Felder innerhalb der übergebenen Puffergrenzen liegen.\n</li><li>Eine Verletzung einer der beiden Längenbedingungen führt zwingend zur Beendigung über den Pfad <code>wrong input</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-489a823a15b84774", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).\n</li><li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array.\n</li><li><code>Length</code>: Länge der Daten in Byte.\n</li><li><code>Offset</code>: Offset-Position des Headers in Byte (implizit/aus Konfiguration referenziert).\n</li></ul>\n</li><li><strong>Knotenelemente</strong>:\n<ul class=\"fig-list\"><li>Initialknoten.\n</li><li>Zwei Entscheidungsknoten (Rauten) zur Zeiger- und Bereichsprüfung.\n</li><li>Drei Aktivitätsendknoten (<code>no</code>, <code>input</code>, <code>wrong</code>), repräsentierend <code>no input</code>, <code>input ok</code> und <code>wrong input</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.\n</li><li>Erste Prüfung am oberen Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no</code> (entspricht <code>no input</code>).\n</li><li>Pfad <code>[TRUE]</code>: Weiterleitung zur kombinierten Längenprüfung.\n</li></ul>\n</li><li>Zweite Prüfung am unteren Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong</code> (entspricht <code>wrong input</code>).\n</li><li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input</code> (entspricht <code>input ok</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\"><li>Zeiger dürfen nicht <code>NULL</code> sein.\n</li><li>Die übergebene Länge <code>Length</code> muss strikt gleich <code>Config-&gt;DataLength/8</code> sein und muss zusätzlich mindestens <code>Offset + 2</code> Byte umfassen, um sicherzustellen, dass die CRC- und Counter-Felder innerhalb der übergebenen Puffergrenzen liegen.\n</li><li>Eine Verletzung einer der beiden Längenbedingungen führt zwingend zur Beendigung über den Pfad <code>wrong input</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-beeac12caf55f8ef", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses der Funktion <code>E2E_P22Protect()</code>. Das Diagramm detailliert den Teilschritt „Verify inputs of the protect function“ innerhalb des End-to-End-Kommunikationsschutzes (E2E Profile 22) der AUTOSAR-Laufzeitbibliothek.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionskontext</strong>: <code>E2E_P22Protect()</code>\n</li><li><strong>Eingangsparameter</strong>:\n<ul class=\"fig-list\"><li><code>Config</code>: Zeiger auf die statische Konfigurationsstruktur des Profils 22 (mit Element <code>DataLength</code> in Bit).\n</li><li><code>State</code>: Zeiger auf den Zustandsspeicher des Senders.\n</li><li><code>Data</code>: Zeiger auf das zu schützende Daten-Array.\n</li><li><code>Length</code>: Länge der Daten in Byte.\n</li><li><code>Offset</code>: Offset-Position des Headers in Byte (implizit/aus Konfiguration referenziert).\n</li></ul>\n</li><li><strong>Knotenelemente</strong>:\n<ul class=\"fig-list\"><li>Initialknoten.\n</li><li>Zwei Entscheidungsknoten (Rauten) zur Zeiger- und Bereichsprüfung.\n</li><li>Drei Aktivitätsendknoten (<code>no</code>, <code>input</code>, <code>wrong</code>), repräsentierend <code>no input</code>, <code>input ok</code> und <code>wrong input</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Beginn am Initialknoten bei Eintritt in die Eingangsverifikation.\n</li><li>Erste Prüfung am oberen Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>no</code> (entspricht <code>no input</code>).\n</li><li>Pfad <code>[TRUE]</code>: Weiterleitung zur kombinierten Längenprüfung.\n</li></ul>\n</li><li>Zweite Prüfung am unteren Entscheidungsknoten:\n<ul class=\"fig-list\"><li>Bedingung <code>Length == Config-&gt;DataLength/8 &amp;&amp; Length &gt;= Offset+2</code>\n</li><li>Pfad <code>[FALSE]</code>: Verzweigung zum Endknoten <code>wrong</code> (entspricht <code>wrong input</code>).\n</li><li>Pfad <code>[TRUE]</code>: Verzweigung zum Endknoten <code>input</code> (entspricht <code>input ok</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Kontrollflussvorgabe für Implementierungen von E2E Profile 22 gemäß PRS_E2E_00529:</p>\n<ul class=\"fig-list\"><li>Zeiger dürfen nicht <code>NULL</code> sein.\n</li><li>Die übergebene Länge <code>Length</code> muss strikt gleich <code>Config-&gt;DataLength/8</code> sein und muss zusätzlich mindestens <code>Offset + 2</code> Byte umfassen, um sicherzustellen, dass die CRC- und Counter-Felder innerhalb der übergebenen Puffergrenzen liegen.\n</li><li>Eine Verletzung einer der beiden Längenbedingungen führt zwingend zur Beendigung über den Pfad <code>wrong input</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-66ff0e305612c605", "to": "FIG-13a23f18d89df96e", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entscheidungsknoten zur Längenprüfung: Die Verzweigungsbedingung wurde von <code>Length == Config-&gt;DataLength/8</code> um die zusätzliche Konjunktion <code>&amp;&amp; Length &gt;= Offset+2</code> erweitert.\n</li><li>Layout / Beschriftungsplatzierung: Die Guard-Bedingungen <code>[FALSE]</code> wurden näher an die Rauten bzw. Pfadursprünge gerückt und Bedingungen mehrzeilig umbrochen.\n</li><li>Endknoten-Beschriftungen: Die Bezeichner an den Activity-Final-Knoten wurden im Bildbeschnitt teils verkürzt/umgebrochen dargestellt (<code>no input</code> -&gt; <code>no</code>, <code>input ok</code> -&gt; <code>input</code>, <code>wrong input</code> -&gt; <code>wrong</code>).\n</li></ul>"}, {"from": "FIG-13a23f18d89df96e", "to": "FIG-489a823a15b84774", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-489a823a15b84774", "to": "FIG-beeac12caf55f8ef", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
